DECLARATIONS.update({'_world_cursor_owner_comparison': {'signature': 'selected: int, compared: int', 'returns': 'WorldCursorRefreshFields', 'flow': 'difference = u16(selected - compared)\nreturn WorldCursorRefreshFields(None, selected, None, None, selected < compared, difference == 0, bool(difference & 32768), bool((selected ^ compared) & (selected ^ difference) & 32768))'}, 'refresh_world_cursor_attribute_fields': {'signature': 'state: SceneState', 'returns': 'WorldCursorRefreshFields', 'flow': 'checked_state(state)\nselected = state.read(4294964086, 2)\nfor address in (4294964858, 4294964860, 4294964862):\n    compared = state.read(address, 2)\n    comparison = _world_cursor_owner_comparison(selected, compared)\n    if comparison.zero:\n        break\nelse:\n    return comparison.validate(state)\nsource = state.table_at(41368).cursor()\nx = state.read(4294964062, 2)\ny = state.read(4294964064, 2)\nattributes = 0\nscroll_x = state.read(4294963988, 2)\nstate.write(4294964746, 2, scroll_x)\nscroll_y = state.read(4294963992, 2)\nstate.write(4294964750, 2, scroll_y)\nfrom .reuse_display import append_map_sprite_fields\nsprite = append_map_sprite_fields(state, source, x, y, attributes, reset_scroll=False, initialize_clip=True).validate(state)\nreturn WorldCursorRefreshFields(sprite.source, sprite.x, sprite.y, sprite.attributes, sprite.carry, sprite.zero, sprite.negative, sprite.overflow).validate(state)'}, 'refresh_world_cursor_attributes_alternate_1': {'signature': 'state: SceneState, inputs: RefreshWorldCursorAttributesAlternate1Input', 'returns': 'RefreshWorldCursorAttributesAlternate1Result', 'flow': "checked_state(state)\nif type(inputs) is not RefreshWorldCursorAttributesAlternate1Input:\n    raise ValueError('function-specific typed input required')\ninputs.validate(state)\nfields = refresh_world_cursor_attribute_fields(state).validate(state)\ndestination = inputs.destination if fields.source_if_written is None else fields.source_if_written\nvalue = replace_word(inputs.value, fields.x)\nfield = inputs.field if fields.y_if_written is None else replace_word(inputs.field, fields.y_if_written)\ntile = inputs.tile if fields.attributes_if_written is None else replace_word(inputs.tile, fields.attributes_if_written)\nreturn RefreshWorldCursorAttributesAlternate1Result(destination=destination, value=value, field=field, tile=tile, carry=fields.carry, zero=fields.zero, negative=fields.negative, overflow=fields.overflow).validate(state)"}})
