DECLARATIONS.update({'copy_scene_palette_longs_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _world_map_frame_fields(state, frame, 16506)\nframe = _movement_move(state, frame, 'target_x', 255, 16)\nwhile True:\n    for source_offset, destination_offset in ((1, 0), (0, 1), (2, 2)):\n        value = frame.roster.byte(0, source_offset)\n        frame = _world_map_store_fields(state, frame, u32(frame.candidates.base + destination_offset), 1, value)\n    frame = first_replace(frame, roster=frame.roster.advance(3), candidates=frame.candidates.advance(3), target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))\n    if low16(frame.target_x) == 65535:\n        return frame"}})

