DECLARATIONS.update({'select_previous_command_officer_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _world_map_frame_fields(state, frame, 24444)\nframe = _campaign_ui_call_fields(state, frame, 23106, 24448)\nframe = _campaign_ui_parallel_cell_fields(state, frame, 0, (60, 30), True)\nframe = _movement_move(state, frame, 'target_x', 7, 16)\nframe = _movement_compare(state, frame, state.read(4294964076, 2), 1, 16)\nload_capacity = False\nif frame.status & 4:\n    for command in (6, 15, 21):\n        frame = _movement_compare(state, frame, state.read(4294964108, 2), command, 16)\n        if frame.status & 4:\n            load_capacity = True\n            break\nif not load_capacity:\n    frame = _movement_test(state, frame, state.read(4294964076, 2), 16)\n    if frame.status & 4:\n        frame = _movement_compare(state, frame, state.read(4294964108, 2), 129, 16)\n        if frame.status & 4:\n            frame = _movement_move(state, frame, 'target_x', 5, 16)\n        else:\n            load_capacity = True\nif load_capacity:\n    frame = _movement_move(state, frame, 'target_y', state.read(4294964132, 2), 16)\n    frame = _city_ui_bit_fields(state, frame, frame.target_y, 14)\n    if not frame.status & 4:\n        frame = _movement_move(state, frame, 'target_x', 5, 16)\nframe = _movement_compare(state, frame, low16(frame.target_x), state.read(4294964074, 2), 16)\nif frame.status & 1 or frame.status & 4:\n    return _command_officer_blank_row_frame_fields(state, frame)\nframe = _movement_move(state, frame, 'choice', state.read(4294964074, 2), 16)\nframe = _city_ui_arithmetic_fields(state, frame, 'choice', state.read(4294964824, 2))\nframe = _movement_move(state, frame, 'offset_y', low16(frame.choice), 16)\nframe = _movement_compare(state, frame, low16(frame.offset_y), state.read(4294964790, 2), 16)\nif not frame.status & 1:\n    frame = _movement_test(state, frame, state.read(4294964822, 2), 16)\n    if not frame.status & 4:\n        frame = _movement_compare(state, frame, low16(frame.offset_y), state.read(4294964790, 2), 16)\n        if frame.status & 4:\n            return _command_officer_extra_row_frame_fields(state, frame)\n    return _command_officer_blank_row_frame_fields(state, frame)\nframe = _campaign_ui_parallel_cell_fields(state, frame, 50050, (30, 60))\nframe = _movement_move(state, frame, 'offset_y', low16(frame.choice), 16)\nframe = _city_ui_shift_fields(state, frame, 'choice', 1)\nframe = _city_ui_arithmetic_fields(state, frame, 'choice', low16(frame.offset_y))\nframe = _city_ui_shift_fields(state, frame, 'choice', 2)\nframe = _movement_compare(state, frame, state.read(4294964932, 2), 1, 16)\nframe = _city_ui_arithmetic_fields(state, frame, 'choice', 49264 if frame.status & 4 else 50800)\nframe = _movement_move(state, frame, 'count', low16(frame.choice), 16)\nframe = _campaign_ui_call_fields(state, frame, 22632, 24610)\nframe = _campaign_ui_parallel_cell_fields(state, frame, 49153, (30,))\nframe = _campaign_ui_parallel_cell_fields(state, frame, 52098, (60, 30))\nfor _cell in (0, 1):\n    frame = _campaign_ui_parallel_cell_fields(state, frame, 0, (60, 30), True)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = _movement_move(state, frame, 'count', 7, 16)\nwhile True:\n    frame = _city_ui_store_fields(state, frame, u32(frame.roster.base + s16(low16(frame.unit)) + 38), 49153)\n    frame = _city_ui_arithmetic_fields(state, frame, 'unit', 2)\n    frame = first_replace(frame, count=replace_word(frame.count, u16(low16(frame.count) - 1)))\n    if low16(frame.count) == 65535:\n        break\nframe = _city_ui_memory_arithmetic_fields(state, frame, 4294964074, 1)\nframe = _city_ui_store_fields(state, frame, u32(frame.roster.base + 60), 0, 2, True)\nreturn _city_ui_memory_arithmetic_fields(state, frame, 4294963994, 90)"}})


